    'identity_zero': ([1], [0]),
    'finite_one': ([0, 1], [0]),
    'finite_two_repeat': ([4], [1]),
    'identity_two_inverse': ([0, 1], [0]),
    'finite_three_common': ([0, 0, 1], [0]),
